import{_ as a,o as t,c as i,a9 as n}from"./chunks/framework.asyjyako.js";const p=JSON.parse('{"title":"Qualified collections","description":"","frontmatter":{},"headers":[],"relativePath":"reference/qualification.md","filePath":"reference/qualification.md","lastUpdated":null}'),o={name:"reference/qualification.md"};function s(c,e,r,l,d,u){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="Qualified-collections" tabindex="-1">Qualified collections <a class="header-anchor" href="#Qualified-collections" aria-label="Permalink to &quot;Qualified collections {#Qualified-collections}&quot;">​</a></h1><p>A PerfChecker release is used with interface packages, Julia versions and external tools. A passing test in one package cannot establish that all these combinations work together. <code>PerfCheckerQualification</code> checks an explicit candidate collection.</p><h2 id="What-is-tested-after-a-change" tabindex="-1">What is tested after a change <a class="header-anchor" href="#What-is-tested-after-a-change" aria-label="Permalink to &quot;What is tested after a change {#What-is-tested-after-a-change}&quot;">​</a></h2><p>Routine CI checks changed interfaces and their consumers with current dependencies on Linux. Core changes also check Windows and the minimum supported Julia version. The shared contracts and style checks accompany the selected components. Core, contract and unknown-path changes conservatively select every component, but still use this reduced profile.</p><p>The extended Windows/Linux matrix runs weekly or on manual request with <code>full</code> enabled. It adds older dependency combinations and broader platform coverage. Only the extended matrix can qualify a release; passing routine CI is not a substitute. Each lane records its runtime and resolved dependency environment.</p><p>The initial supported qualification platforms are Windows and Linux. Jobs execute sequentially, with one Julia compute thread and single-thread BLAS defaults, within a four-thread computation budget. No measurement is validated merely because a tool executable was found.</p><h2 id="Candidate-versus-qualified" tabindex="-1">Candidate versus qualified <a class="header-anchor" href="#Candidate-versus-qualified" aria-label="Permalink to &quot;Candidate versus qualified {#Candidate-versus-qualified}&quot;">​</a></h2><p><code>qualification/collection.toml</code> selects candidates. External repositories use full commit SHAs; mutable branches are rejected. A dependency-update PR proposes a new candidate and triggers qualification. Until it passes, the last qualified collection remains the published reference.</p><p>Every qualification attempt has its own campaign ID. Missing jobs cannot be filled with reports from an earlier attempt, even at the same source revision. Failed, cancelled, skipped, duplicate or mismatched records prevent full qualification.</p><p>The resulting inventory identifies the exact package versions and environment fingerprints used in each lane. It describes several environments, rather than claiming all interfaces can share one Manifest. This matters for HTTP dependencies.</p><h2 id="Documentation-publication" tabindex="-1">Documentation publication <a class="header-anchor" href="#Documentation-publication" aria-label="Permalink to &quot;Documentation publication {#Documentation-publication}&quot;">​</a></h2><p>Documentation publication is independent of qualification. The <code>Documentation</code> workflow installs the documentation dependencies, builds Documenter and VitePress, and publishes <code>/PerfChecker/dev/</code>. It runs no package matrix, browser tests or benchmarks. Documenter&#39;s own reference and doctest checks remain part of the build.</p><p>The extended qualification produces its own <code>qualified-collection</code> artifact with the exact tested package revisions and environments. Only complete successful qualification authorizes a package release. Publishing development documentation does not certify the packages it describes. Pull requests build but cannot publish.</p>',13)])])}const f=a(o,[["render",s]]);export{p as __pageData,f as default};
